import { Client } from "@modelcontextprotocol/sdk/client/index.js";

const client = new Client(
  { name: "my-host-app", version: "1.0.0" },
  { capabilities: {} }
);

import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

const transport = new StdioClientTransport({
  command: "python",
  args: ["weather_server.py"]
});

await client.connect(transport);

// wrong: not awaiting connect before using the client
client.connect(transport);
const tools = await client.listTools(); // may run before initialize finishes

// right: await the full handshake first
await client.connect(transport);
const tools = await client.listTools();

const caps = client.getServerCapabilities();

if (!caps?.resources) {
  console.warn("server does not support resources, skipping resource features");
}

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

async function startClient() {
  console.log("stage=creating_instance");
  const client = new Client(
    { name: "demo-host", version: "1.0.0" },
    { capabilities: {} }
  );

  console.log("stage=opening_transport");
  const transport = new StdioClientTransport({
    command: "python",
    args: ["weather_server.py"]
  });

  console.log("stage=connecting");
  await client.connect(transport);
  console.log("stage=handshake_complete");

  const caps = client.getServerCapabilities();
  console.log("stage=capabilities_received", caps);

  const tools = await client.listTools();
  console.log("stage=ready", tools.tools.length, "tools available");

  return client;
}

startClient().catch((err) => {
  console.error("stage=failed", err);
  process.exit(1);
});
